style.css:
@-moz-document domain("instagram.com") {
/* Cor de fundo geral azul Teams */
body, html, ._a3wf, ._a3wj, ._a3wh, ._a3wm, ._a3wo {
    background-color: #464EB8 !important; /* Azul padrão Teams */
    color: white !important;
}

/* Esconde fotos de perfil */
img[alt*="profile"], img[decoding="auto"], img[src*="profile"], img[class*="profile"] {
    display: none !important;
}

/* Esconde imagens dos stories e posts */
._aagw img, article img, ._aagt img {
    display: none !important;
}

/* Esconde a barra lateral que mostra "Explorar", "Reels", etc */
nav, ._ac7b, ._ac7a, aside, header {
    background: #3A42A8 !important;
    color: white !important;
}

/* Esconde ícones denunciadores */
svg, path {
    fill: white !important;
}

/* Bordas sutis para parecer mais Teams */
._ac7b, ._ac7a, ._a3wf, ._a3wj, article, main, section {
    border: 1px solid #5A62C8 !important;
    border-radius: 6px;
}

/* Fonte padrão semelhante ao Teams */
body, div, span, a, p {
    font-family: "Segoe UI", "Helvetica Neue", sans-serif !important;
}

/* Remove vídeos de perfil e stories */
video {
    display: none !important;
}

/* Corrige botões */
button {
    background-color: #5A62C8 !important;
    color: white !important;
    border: none !important;
}

/* Remove nomes de usuários das fotos */
._aacl, ._aaco, ._aacw {
    display: none !important;
}

/* Remove o logo do Instagram */
header svg, header img {
    display: none !important;
}

/* Remove sugestões de seguidores */
section[role="presentation"], section[role="region"] {
    display: none !important;
}

/* Ajuste geral de contraste */
* {
    filter: brightness(1.1) contrast(1.2);
}
}
